def gravity(coords, dr, dc, n=18):
    a=np.zeros((n,n),dtype=int)
    for r,c in coords:a[r,c]=1
    moved=True
    while moved:
        moved=False
        rows=range(n) if dr<0 else range(n-1,-1,-1)
        cols=range(n) if dc<0 else range(n-1,-1,-1)
        for r in rows:
            for c in cols:
                if a[r,c] and 0<=r+dr<n and 0<=c+dc<n and not a[r+dr,c+dc]:
                    a[r,c]=0;a[r+dr,c+dc]=1;moved=True
    return set(map(tuple,np.argwhere(a)))
